import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;

import java.io.File;
import java.util.Locale;

public class IconDetector extends Detector implements Detector.BinaryResourceScanner {

    public static final Issue ICON_LOCATION = Issue.create(
            "IconLocation",
            "Image defined in density-independent drawable folder",
            "The `res/drawable` folder is intended for density-independent graphics such as shapes "
                    + "defined in XML. For bitmaps, move the file to `drawable-mdpi` and consider "
                    + "providing higher and lower resolution versions in `drawable-ldpi`, "
                    + "`drawable-hdpi` and `drawable-xhdpi`. If the icon really is density "
                    + "independent (for example a solid color) you can place it in `drawable-nodpi`.",
            Category.ICONS,
            5,
            Severity.WARNING,
            new Implementation(IconDetector.class, Scope.BINARY_RESOURCE_FILE_SCOPE))
            .addMoreInfo("https://developer.android.com/guide/practices/screens_support.html");

    @Override
    public void checkBinaryResource(ResourceContext context) {
        if (context.getResourceFolderType() != ResourceFolderType.DRAWABLE) {
            return;
        }

        File file = context.file;
        String folder = file.getParentFile().getName();
        if (!"drawable".equals(folder)) {
            return;
        }

        String name = file.getName();
        if (isBitmap(name)) {
            context.report(ICON_LOCATION, Location.create(file),
                    "Bitmaps should not be placed in the density-independent `drawable` folder");
        }
    }

    private static boolean isBitmap(String name) {
        int dot = name.lastIndexOf('.');
        if (dot == -1) {
            return false;
        }

        String ext = name.substring(dot + 1).toLowerCase(Locale.US);
        switch (ext) {
            case "png":
                if (name.length() >= 6
                        && name.regionMatches(true, name.length() - 6, ".9.png", 0, 6)) {
                    return false;
                }
                return true;
            case "jpg":
            case "jpeg":
            case "gif":
            case "webp":
                return true;
            default:
                return false;
        }
    }
}
